from typing import List, Dict, Any, Optional
from pydantic import BaseModel, Field


class InventoryFinding(BaseModel):
    """Structured findings generated by the Inventory Intelligence Agent."""
    requested_blood_group: str
    component_type: str = "RBC"
    compatible_groups: List[str] = Field(default_factory=list)
    network_stock: Dict[str, Any] = Field(default_factory=dict)
    total_usable_units: int = 0
    total_available_units: int = 0
    total_safety_reserve: int = 0
    regional_deficit: bool = False
    usable_stock_verified: bool = True
    candidate_facilities_count: int = 0
    summary: str = ""


class DemandFinding(BaseModel):
    """Structured findings generated by the Demand & Surge Forecasting Agent."""
    urgency_level: str
    units_requested: int
    surge_risk: str = "MODERATE"  # HIGH, MODERATE, LOW
    consumption_velocity_index: float = 1.0
    recommended_buffer_multiplier: float = 1.0
    post_transfer_stockout_risk: str = "LOW"  # HIGH, MODERATE, LOW
    safe_transfer_threshold: int = 2
    summary: str = ""


class MatchingFinding(BaseModel):
    """Structured findings generated by the Matching & Allocation Agent."""
    request_blood_group: str
    units_requested: int
    urgency: str
    total_candidates_evaluated: int = 0
    feasible_candidates_count: int = 0
    sufficient_inventory: bool = True
    top_candidates: List[Dict[str, Any]] = Field(default_factory=list)
    allocation_strategy: str = "SINGLE_SOURCE"  # SINGLE_SOURCE, SPLIT_ALLOCATION, STANDBY_ESCALATION
    recommended_sources: List[Dict[str, Any]] = Field(default_factory=list)
    summary: str = ""


class LogisticsFinding(BaseModel):
    """Structured findings generated by the Logistics & Routing Agent."""
    selected_transport_mode: str = "STANDARD_COURIER"  # AMBULANCE_SIREN, STANDARD_COURIER (drones disallowed in emergency blood dispatch)
    target_eta_minutes: int = 45
    corridor_evaluations: List[Dict[str, Any]] = Field(default_factory=list)
    cold_chain_verified: bool = True
    cold_chain_spec: Dict[str, Any] = Field(default_factory=dict)
    traffic_monitoring_active: bool = True
    summary: str = ""


class DonorFinding(BaseModel):
    """Structured findings generated by the Donor Intelligence & Standby Agent."""
    blood_group: str
    simulation_mode: bool = True
    disclaimer: str = "Potential synthetic donor candidates identified for simulation/standby protocol only. No real donor contact or clinical eligibility verified."
    total_donors_in_pool: int = 0
    available_immediate_count: int = 0
    standby_on_call_count: int = 0
    candidate_donors: List[Dict[str, Any]] = Field(default_factory=list)
    donor_strategy: str = "ROUTINE_MONITORING"  # STANDBY_MOBILIZATION, ROUTINE_MONITORING, IMMEDIATE_ALERT
    summary: str = ""


class ExplainabilityFinding(BaseModel):
    """Structured findings generated by the Explainability & Verification Agent."""
    clinical_rationale: str
    candidate_selection_reasoning: str
    rejected_alternatives: List[Dict[str, Any]] = Field(default_factory=list)
    constraints_evaluated: List[str] = Field(default_factory=list)
    trade_offs: List[str] = Field(default_factory=list)
    safety_validation: Optional[Dict[str, Any]] = None
    safety_verified: bool = False
    decision_confidence: float = 0.95
    dispatch_instructions: List[str] = Field(default_factory=list)
    summary: str = ""
